window.GUIDE={"cats": {"sights": {"sec": "see", "title": "Sights", "emoji": "🏰", "color": "#E8483B"}, "museums": {"sec": "see", "title": "Museums", "emoji": "🖼️", "color": "#1877D0"}, "galleries": {"sec": "see", "title": "Galleries", "emoji": "🎨", "color": "#8E44C9"}, "shops": {"sec": "see", "title": "Shops & markets", "emoji": "🛍️", "color": "#E8930C"}, "near": {"sec": "see", "title": "Near the hotel", "emoji": "📍", "color": "#0F9D8A"}, "cafes": {"sec": "eat", "title": "Cafés", "emoji": "☕", "color": "#0F9D8A"}, "tapas": {"sec": "eat", "title": "Budget tapas", "emoji": "🍤", "color": "#E8483B"}, "mid": {"sec": "eat", "title": "Mid-range", "emoji": "🍽️", "color": "#E8930C"}, "splurge": {"sec": "eat", "title": "Splurge & Michelin", "emoji": "⭐", "color": "#8E44C9"}, "bars": {"sec": "eat", "title": "Bars & rooftops", "emoji": "🍸", "color": "#1877D0"}, "gay": {"sec": "eat", "title": "Gay & gay-friendly", "emoji": "🏳️‍🌈", "color": "#E5007E"}, "outdoor": {"sec": "see", "title": "Outdoors & beaches", "emoji": "🌊", "color": "#0EA5A4"}, "world": {"sec": "eat", "title": "Around the world", "emoji": "🌍", "color": "#0F766E"}, "cash": {"sec": "see", "title": "Cash machines", "emoji": "🏧", "color": "#16A34A"}}, "items": [{"id": "s1", "cat": "sights", "name": "Alcazaba", "addr": "Calle Alcazabilla 2, 29012", "text": "Málaga's 11th-century Moorish palace-fortress climbs the hillside in tiers of walls, horseshoe arches and fountain-cooled patios. Go early to have the gardens to yourself, and look back over the Roman Theatre from the lower ramparts. Allow 1–1½ hours.", "tip": "Arrive early for quieter walls", "lat": 36.7212, "lon": -4.4157, "price": 0, "walk": 16, "img": "img/s1.svg", "q": "Alcazaba, Calle Alcazabilla 2, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s2", "cat": "sights", "name": "Castillo de Gibralfaro", "addr": "Camino de Gibralfaro 11, 29016", "text": "The 14th-century Nasrid castle crowning the hill above the Alcazaba. Walk the full circuit of ramparts for the best panorama in the city – the port, the bullring, the cathedral roof and the coast to the east. The walk up is steep; the bus up and stroll down is the sensible combination.", "tip": "Bus 35, or a steep 25-min walk", "lat": 36.7232, "lon": -4.4105, "price": 0, "walk": 23, "img": "img/s2.svg", "q": "Castillo de Gibralfaro, Camino de Gibralfaro 11, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s3", "cat": "sights", "name": "Teatro Romano", "addr": "Calle Alcazabilla s/n, 29015", "text": "A 1st-century BC Roman theatre, buried for centuries and rediscovered only in 1951. You can sit on the restored stone tiers, and a small free interpretation centre explains the excavations. Lovely at dusk, when the Alcazaba walls above are floodlit.", "tip": "Free entry", "lat": 36.7214, "lon": -4.417, "price": 0, "walk": 14, "img": "img/s3.svg", "q": "Teatro Romano, Calle Alcazabilla s, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s4", "cat": "sights", "name": "Catedral de la Encarnación", "addr": "Calle Molina Lario 9, 29015", "text": "Nicknamed 'La Manquita' – the one-armed lady – because its south tower was never finished. Built between the 16th and 18th centuries, it mixes Gothic, Renaissance and Baroque. The guided rooftop walk is the highlight: you stand right on the vaulting with the city around you.", "tip": "Book the rooftop tour", "lat": 36.7199, "lon": -4.4194, "price": 0, "walk": 11, "img": "img/s4.svg", "q": "Catedral de la Encarnación, Calle Molina Lario 9, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s5", "cat": "sights", "name": "Soho – Barrio de las Artes", "addr": "Around Calle Tomás Heredia & Calle Casas de Campo, 29001", "text": "A once-run-down grid between the Alameda and the port, reinvented through a residents' street-art project. Whole building façades are covered with large-scale murals by Spanish and international artists. Wander freely – new pieces keep appearing – and combine with the galleries and cafés nearby.", "tip": "Best on foot, any time", "lat": 36.7172, "lon": -4.4232, "price": 0, "walk": 9, "img": "img/s5.svg", "q": "Soho Barrio de las Artes, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s6", "cat": "sights", "name": "Muelle Uno & Palmeral", "addr": "Paseo del Muelle Uno, 29016", "text": "The redeveloped harbour front: a palm-lined promenade (the Palmeral de las Sorpresas) with a sculptural pergola, leading onto Muelle Uno's waterside shops and restaurants, the Pompidou cube and La Farola lighthouse. Easy, flat and great for an evening paseo.", "tip": "Sunset stroll", "lat": 36.717, "lon": -4.4133, "price": 0, "walk": 21, "img": "img/s6.svg", "q": "Muelle Uno, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s7", "cat": "museums", "name": "Museo Picasso Málaga", "addr": "Calle San Agustín 8, 29015 (Palacio de Buenavista)", "text": "The city's most visited museum, in a beautiful 16th-century palace. The collection spans Picasso's whole career, with temporary exhibitions alongside. Don't miss the basement, where Phoenician and Roman remains found during the restoration are on view. Book a timed slot to skip the queue.", "tip": "Daily from 10:00 · free last 2 hrs on Sundays", "lat": 36.7218, "lon": -4.4183, "price": 0, "walk": 12, "img": "img/s7.svg", "q": "Museo Picasso Málaga, Calle San Agustín 8, Málaga", "ta": true, "far": false, "web": "https://museopicassomalaga.org/en"}, {"id": "s8", "cat": "museums", "name": "Museo Casa Natal Picasso", "addr": "Plaza de la Merced 15, 29012", "text": "The house where Picasso was born in 1881, on the lively Plaza de la Merced. A recreated family apartment, personal mementoes, sketchbooks, prints and ceramics give an intimate picture of his early years. Small, so 45 minutes is plenty – then sit with his bronze statue on the plaza bench.", "tip": "Combine with Plaza de la Merced", "lat": 36.7233, "lon": -4.4162, "price": 0, "walk": 15, "img": "img/s8.svg", "q": "Museo Casa Natal Picasso, Plaza de la Merced 15, Málaga", "ta": true, "far": false, "web": "http://www.museocasanatalpicasso.malaga.eu"}, {"id": "s9", "cat": "museums", "name": "Museo Carmen Thyssen", "addr": "Plaza Carmen Thyssen, Calle Compañía 10, 29008", "text": "Superb 19th- and early 20th-century Spanish painting – Andalusian landscapes, costumbrista street scenes, Sorolla and Romero de Torres – in the restored 16th-century Palacio de Villalón. Arguably the most rewarding art collection in the city if you like figurative painting; strong temporary shows too.", "tip": "Tue–Sun · closed Mondays", "lat": 36.72153, "lon": -4.42264, "price": 0, "walk": 6, "img": "img/s9.svg", "q": "Museo Carmen Thyssen, Plaza Carmen Thyssen, Málaga", "ta": true, "far": false, "web": "https://www.carmenthyssenmalaga.org/en/"}, {"id": "s10", "cat": "museums", "name": "Museo de Málaga", "addr": "Plaza de la Aduana s/n, 29015 (Palacio de la Aduana)", "text": "Málaga's big civic museum fills the grand neoclassical former Customs House: one floor of fine art (17th–20th century Spanish painting) and one of archaeology, from prehistory through Phoenician and Roman finds. Often overlooked and rarely crowded – a real sleeper. Note: entry is free for EU citizens only.", "tip": "Small fee for non-EU visitors", "lat": 36.7203, "lon": -4.4163, "price": 0, "walk": 15, "img": "img/s10.svg", "q": "Museo de Málaga, Plaza de la Aduana s, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s11", "cat": "museums", "name": "Centre Pompidou Málaga", "addr": "Pasaje Doctor Carrillo Casaux s/n, Muelle Uno, 29016", "text": "Look for the multicoloured glass cube on the quayside – the museum is underneath. A satellite of the Paris Pompidou showing 20th- and 21st-century art from its collection, from Bacon and Kahlo to contemporary installation. The partnership has been extended to 2034, so it's here to stay.", "tip": "Closed Tuesdays · around €9", "lat": 36.7189, "lon": -4.4125, "price": 0, "walk": 21, "img": "img/s11.svg", "q": "Centre Pompidou Málaga, Pasaje Doctor Carrillo Casaux s, Málaga", "ta": true, "far": false, "web": "https://www.centrepompidou-malaga.eu"}, {"id": "s12", "cat": "museums", "name": "Museo del Vidrio y Cristal", "addr": "Plazuela Santísimo Cristo de la Sangre 2, 29013", "text": "A hidden gem: a private collection of some 3,000 pieces of glass – Roman to Art Nouveau, with stained glass and period furniture – displayed in an 18th-century house in the old Capuchinos quarter. Visits are usually guided by the owners and are wonderfully personal.", "tip": "Guided visits – ring ahead", "lat": 36.7258, "lon": -4.4213, "price": 0, "walk": 11, "img": "img/s12.svg", "q": "Museo del Vidrio y Cristal, Plazuela Santísimo Cristo de la Sangre 2, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s13", "cat": "museums", "name": "Museo Revello de Toro", "addr": "Calle Afligidos 5, 29015", "text": "Portraits and figure paintings by Málaga artist Félix Revello de Toro, shown in a charming 17th-century house that was once the workshop of Baroque sculptor Pedro de Mena. Quiet, intimate and a short step from the cathedral.", "tip": "Free entry", "lat": 36.7203, "lon": -4.4183, "price": 0, "walk": 12, "img": "img/s13.svg", "q": "Museo Revello de Toro, Calle Afligidos 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s14", "cat": "museums", "name": "Colección del Museo Ruso & MEET", "addr": "Edificio Tabacalera, Av. Sor Teresa Prat 15, 29003", "text": "Set in the handsome 1920s former Royal Tobacco Factory. Alongside the Russian-art programme, the building now hosts MEET (Málaga Espacio Expositivo Tabacalera), with its own rotating exhibitions of photography and painting. Worth the short trip out of the centre; check what's showing before you go.", "tip": "2.5 km west – bus or taxi", "lat": 36.6992, "lon": -4.4386, "price": 0, "walk": 44, "img": "img/s14.svg", "q": "Colección del Museo Ruso, Avenida Sor Teresa Prat 15, Málaga", "ta": true, "far": true, "web": "https://www.meet-malaga.eu"}, {"id": "s15", "cat": "galleries", "name": "MUCAC La Coracha", "addr": "Paseo de Reding 1, 29016", "text": "The new municipal museum of contemporary art (it absorbed the old CAC and MUPAM). This site, tucked into the foot of the Gibralfaro hill, shows the city's collection alongside changing exhibitions with a focus on Málaga, Andalusian, Mediterranean and Latin American artists.", "tip": "Tue–Sun 10:00–14:00 & 17:30–21:30 · closed Mon", "lat": 36.7203, "lon": -4.4135, "price": 0, "walk": 19, "img": "img/s15.svg", "q": "MUCAC La Coracha, Paseo de Reding 1, Málaga", "ta": true, "far": false, "web": "https://mucacmalaga.eu/"}, {"id": "s16", "cat": "galleries", "name": "MUCAC Mayoristas (former CAC)", "addr": "Calle Alemania s/n, 29001", "text": "The former CAC Málaga, one of Spain's best-known contemporary art centres, housed in a 1930s wholesale market by the Guadalmedina. It closed in 2024 for conversion into the second MUCAC site, with a 2026 reopening planned. If it's open during your trip, it's essential; if not, admire the building and the Soho murals around it.", "tip": "Check reopening status before visiting", "lat": 36.7144, "lon": -4.4256, "price": 0, "walk": 13, "img": "img/s16.svg", "q": "MUCAC Mayoristas, Calle Alemania, Málaga", "ta": true, "far": false, "web": "https://mucacmalaga.eu/"}, {"id": "s17", "cat": "galleries", "name": "JM Galería", "addr": "Calle Duquesa de Parcent 12, 29001 (Soho)", "text": "Founded in 2001 by gallerist Javier Marín, this is one of the city's leading private contemporary galleries – a big, multi-level space that suits ambitious installations and solo shows. Sitting in the middle of Soho, it pairs naturally with a mural walk.", "tip": "Mon–Fri 11:00–14:00 & 17:30–20:30 · closed weekends", "lat": 36.7168, "lon": -4.424, "price": 0, "walk": 9, "img": "img/s17.svg", "q": "JM Galería, Calle Duquesa de Parcent 12, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s18", "cat": "galleries", "name": "Galería Isabel Hurley", "addr": "Paseo de Reding 39, 29016", "text": "A pioneer of Málaga's contemporary art scene since the late 20th century, showing established and emerging Spanish and international artists. On the elegant Paseo de Reding near the bullring – a pleasant walk along from MUCAC La Coracha.", "tip": "Tue–Fri 11:00–13:30 & 17:30–20:30 · closed Sat–Mon", "lat": 36.7212, "lon": -4.409, "price": 0, "walk": 25, "img": "img/s18.svg", "q": "Galería Isabel Hurley, Paseo de Reding 39, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s19", "cat": "galleries", "name": "Galería Javier Román", "addr": "Calle San Juan de Letrán 10, 29012", "text": "Running since 1999, this respected independent gallery promotes contemporary Spanish artists with a carefully curated, frequently changing programme, and appears at the major art fairs. A good stop after the Casa Natal Picasso.", "tip": "Not confirmed open · check before visiting", "lat": 36.7248, "lon": -4.4172, "price": 0, "walk": 15, "img": "img/s19.svg", "q": "Galería Javier Román, Calle San Juan de Letrán 10, Málaga", "ta": true, "far": false, "web": "https://www.galeriajavierroman.com"}, {"id": "s20", "cat": "galleries", "name": "La Térmica", "addr": "Av. de los Guindos 48, 29004", "text": "A multidisciplinary cultural centre in a grand early-20th-century building, mixing contemporary art and photography exhibitions with design, talks, music and occasional evening events. Check the programme online – it's well worth the trip when there's a good show on.", "tip": "3.5 km west – bus or taxi", "lat": 36.6894, "lon": -4.4454, "price": 0, "walk": 64, "img": "img/s20.svg", "q": "La Térmica, Av. de los Guindos 48, Málaga", "ta": true, "far": true, "web": ""}, {"id": "s21", "cat": "shops", "name": "Mercado Central de Atarazanas", "addr": "Calle Atarazanas 10, 29005", "text": "Málaga's 19th-century iron-and-glass food market, entered through a horseshoe arch surviving from the Moorish shipyard that once stood here. Look up at the huge stained-glass window, then browse the stalls for almonds, olives, dried fruit, cured ham and local cheese – easy, packable presents.", "tip": "Mon–Sat mornings; closed Sundays", "lat": 36.7186, "lon": -4.4245, "price": 0, "walk": 6, "img": "img/s21.svg", "q": "Mercado Central de Atarazanas, Calle Atarazanas 10, Málaga", "ta": true, "far": false, "web": "https://mercadomalaga.es"}, {"id": "s22", "cat": "shops", "name": "Calle Larios & side streets", "addr": "Calle Marqués de Larios, 29005 → Plaza de la Constitución", "text": "The city's elegant, marble-paved, pedestrianised showcase street (1891), now mostly big names. The independent character lives in the lanes either side – Calle Nueva, Calle Especería and Calle Granada – with old family shops selling hand-painted fans, espadrilles, leather and religious crafts.", "tip": "Shops close Sundays", "lat": 36.7198, "lon": -4.422, "price": 0, "walk": 7, "img": "img/s22.svg", "q": "Calle Marqués de Larios, Málaga", "ta": false, "far": false, "web": ""}, {"id": "s23", "cat": "shops", "name": "Casa Mira", "addr": "Calle Marqués de Larios 5, 29015", "text": "A Málaga institution since 1890, still family-run. Famous for its turrón (almond nougat), sold by weight to take home, and for its turrón ice cream – the perfect break from Calle Larios.", "tip": "Try turrón ice cream", "lat": 36.7189, "lon": -4.4215, "price": 0, "walk": 9, "img": "img/s23.svg", "q": "Casa Mira, Calle Marqués de Larios 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s24", "cat": "shops", "name": "La Recova", "addr": "Pasaje Ntra. Sra. de los Dolores de San Juan 5, 29005", "text": "Half craft-and-antique shop, half tiny café, crammed with Spanish ceramics, tiles, baskets, birdcages and curiosities collected from traditional workshops around Spain. Shop for a hand-painted plate, then stay for a rustic breakfast of pan cateto with a coffee.", "tip": "Mornings · closed weekends", "lat": 36.72, "lon": -4.4258, "price": 0, "walk": 3, "img": "img/s24.svg", "q": "La Recova, Pasaje Ntra. Sra. de los Dolores de San Juan 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s25", "cat": "shops", "name": "Antigua Casa de Guardia", "addr": "Alameda Principal 18, 29005", "text": "Málaga's oldest tavern, founded in 1840: barrels line the walls, wine is poured straight from the cask and your tab is chalked on the wooden bar. Taste the local sweet wines (Moscatel, Málaga Dulce, Pajarete 1908) and buy bottles from the bodega to bring home. Its house vermouth is a classic: order a glass before lunch, the way locals do.", "tip": "Buy a bottle of Pajarete", "lat": 36.7181, "lon": -4.4232, "price": 0, "walk": 8, "img": "img/s25.svg", "q": "Antigua Casa de Guardia, Alameda Principal 18, Málaga", "ta": true, "far": false, "web": ""}, {"id": "s26", "cat": "shops", "name": "Mercado Urbano del Soho", "addr": "Calle Tomás Heredia, 29001", "text": "A monthly street market of more than fifty local makers – ceramics, jewellery, illustration, prints, fashion and design – set among the Soho murals. The next date after your arrival is Sunday 22 November; check before you plan around it.", "tip": "4th Sunday of the month, 11:00–19:00", "lat": 36.7157, "lon": -4.4248, "price": 0, "walk": 11, "img": "img/s26.svg", "q": "Calle Tomás Heredia, Málaga", "ta": false, "far": false, "web": ""}, {"id": "nA", "cat": "near", "name": "Iglesia de Santo Domingo", "addr": "Calle Cerrojo 1", "text": "Around the corner from the hotel, by the river. The largest church in the historic centre after the cathedral, Gothic-Mudéjar in origin, and home of the Cristo de Mena carried by the Spanish Legion each Maundy Thursday. Pop in if the doors are open.", "tip": "", "lat": 36.7194, "lon": -4.4263, "price": 0, "walk": 4, "img": "img/nA.svg", "q": "Iglesia de Santo Domingo, Calle Cerrojo 1, Málaga", "ta": true, "far": false, "web": ""}, {"id": "nB", "cat": "near", "name": "Museum Jorge Rando", "addr": "Calle Cruz del Molinillo 12, 29013", "text": "Free, calm and surprisingly little visited. Spain's museum of Expressionism, built around the bold paintings of Málaga-born Jorge Rando, with bright, skylit galleries in the former Mercedarian convent cloister. Closed Sundays. About 10 minutes' walk, next to the Glass Museum (no. 12).", "tip": "", "lat": 36.727, "lon": -4.4232, "price": 0, "walk": 11, "img": "img/nB.svg", "q": "Museum Jorge Rando, Calle Cruz del Molinillo 12, Málaga", "ta": true, "far": false, "web": "https://www.museojorgerando.org"}, {"id": "nC", "cat": "near", "name": "Kelipe Centro de Arte Flamenco", "addr": "Calle Muro de Puerta Nueva 10, 29005", "text": "An intimate flamenco venue just over the Santo Domingo bridge, with small-audience shows of guitar, song and dance. It's the easy evening option close to the hotel. Book a day or two ahead.", "tip": "", "lat": 36.7227, "lon": -4.4266, "price": 0, "walk": 2, "img": "img/nC.svg", "q": "Kelipe Centro de Arte Flamenco, Calle Muro de Puerta Nueva 10, Málaga", "ta": true, "far": false, "web": ""}, {"id": "nD", "cat": "near", "name": "El Corte Inglés", "addr": "Av. de Andalucía 4–6, 29007", "text": "Spain's big department store, about 12 minutes' walk west. Useful for anything you've forgotten, and its gourmet food hall is handy for Spanish olive oil, wine, ham and nicely packaged edible gifts to take home.", "tip": "", "lat": 36.717, "lon": -4.4279, "price": 0, "walk": 9, "img": "img/nD.svg", "q": "El Corte Inglés, Av. de Andalucía 4–6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "nE", "cat": "near", "name": "Mercado del Carmen", "addr": "Calle la Serna 3, El Perchel, 29002", "text": "El Perchel is one of Málaga's oldest working-class barrios. Its neighbourhood market is a more local alternative to Atarazanas, with fish and produce stalls and a lively tapas area that fills up at weekend lunchtimes. About 16 minutes' walk south.", "tip": "", "lat": 36.714, "lon": -4.4318, "price": 0, "walk": 16, "img": "img/nE.svg", "q": "Mercado del Carmen, Calle la Serna 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "nG", "cat": "near", "name": "Iglesia de San Pablo", "addr": "Calle Trinidad, Trinidad quarter, 29001", "text": "A parish church in the Trinidad quarter, a short walk from the hotel. Its big moment is Holy Monday, when the Jesús Cautivo image is carried through the streets. Pop in if the doors are open.", "tip": "", "lat": 36.7208, "lon": -4.4296, "price": 0, "walk": 5, "img": "img/nG.svg", "q": "Iglesia de San Pablo, Calle Trinidad, Málaga", "ta": true, "far": false, "web": ""}, {"id": "nF", "cat": "near", "name": "Málaga Centro-Alameda station", "addr": "Av. de Andalucía, by the Puente de Tetuán", "text": "The city-centre terminus of the C1 airport train, about 10 minutes' walk from the hotel. Handy for arrival and departure, and also the line for day trips along the coast to Torremolinos, Benalmádena or Fuengirola.", "tip": "", "lat": 36.7177, "lon": -4.4256, "price": 0, "walk": 7, "img": "img/nF.svg", "q": "Estación Málaga Centro-Alameda", "ta": false, "far": false, "web": ""}, {"id": "e1", "cat": "cafes", "name": "Sentir Café", "addr": "Trinidad Grund 10, 29001", "text": "A calm specialty café a few minutes from the Atarazanas market, with a brunch menu, free Wi-Fi and a room made for longer stays. A good place to slow down after a morning of museums.", "tip": "Opens 09:30 · check the days", "lat": 36.7183, "lon": -4.4238, "price": 2, "walk": 7, "img": "img/e1.svg", "q": "Sentir Café, Trinidad Grund 10, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e2", "cat": "cafes", "name": "Casa Aranda", "addr": "Calle Herrería del Rey 3, 29005", "text": "Málaga's churros institution since 1932, filling a whole alley beside the Atarazanas market with waiter-served tables. Order churros with a cup of thick hot chocolate for dipping, plus a coffee the Málaga way. Fast, noisy, cheap and wonderful.", "tip": "Breakfast · go early", "lat": 36.7191, "lon": -4.4238, "price": 1, "walk": 6, "img": "img/e2.svg", "q": "Casa Aranda, Calle Herrería del Rey 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e3", "cat": "cafes", "name": "Bertani Café", "addr": "Calle San Juan 40, 29005", "text": "Widely credited as the city's first specialty coffee bar: a small, serious counter of carefully sourced espresso and filter with homemade cakes. A couple of minutes from La Recova and an easy first stop on the walk in from your hotel.", "tip": "Closed Sundays", "lat": 36.7203, "lon": -4.4235, "price": 2, "walk": 5, "img": "img/e3.svg", "q": "Bertani Café, Calle San Juan 40, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e4", "cat": "cafes", "name": "Kima Coffee", "addr": "Calle Carretería 67, 29008", "text": "A roastery-café on Calle Carretería that roasts single-origin beans in-house, served as espresso or filter. A calm, modern spot with good bags of beans to take home.", "tip": "Closed Sundays", "lat": 36.7232, "lon": -4.4238, "price": 2, "walk": 5, "img": "img/e4.svg", "q": "Kima Coffee, Calle Carretería 67, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e5", "cat": "cafes", "name": "Mía Coffee", "addr": "Calle Vendeja 9", "text": "A tiny specialty bar on a pretty little square, where the owner brews carefully and bakes the homemade cakes, including vegan ones, that disappear by mid-afternoon. A favourite with locals for a quiet coffee.", "tip": "Cakes sell out early", "lat": 36.7165, "lon": -4.4229, "price": 2, "walk": 11, "img": "img/e5.svg", "q": "Mía Coffee, Calle Vendeja 9, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e6", "cat": "cafes", "name": "Next Level Specialty Coffee", "addr": "Calle Panaderos 14, 29005", "text": "A bright little bar just off the Alameda, with rotating single-origin filters and one of the best brunch menus in town. It's good for a proper sit-down breakfast before a museum morning, and is close to the hotel.", "tip": "Daily, from 07:30", "lat": 36.7186, "lon": -4.4228, "price": 2, "walk": 8, "img": "img/e6.svg", "q": "Next Level Specialty Coffee, Calle Panaderos 14, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e7", "cat": "cafes", "name": "Café con Libros", "addr": "Plaza de la Merced 19, 29012", "text": "An old-style reading-room café on Plaza de la Merced, lined with books, with coffee and cake by day and cultural events and drinks into the evening. Next door to Picasso's birthplace.", "tip": "Not confirmed on Google · check before visiting", "lat": 36.7238, "lon": -4.4172, "price": 1, "walk": 14, "img": "img/e7.svg", "q": "Café con Libros, Plaza de la Merced 19, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e8", "cat": "cafes", "name": "La Tetería", "addr": "Calle San Agustín 9, 29015", "text": "A cosy Moorish-style tea house almost opposite the Picasso Museum. Expect dozens of teas, Moroccan mint tea poured from a height, and sticky North African pastries. Lovely on a cooler November afternoon.", "tip": "After the Picasso Museum", "lat": 36.7213, "lon": -4.4187, "price": 1, "walk": 11, "img": "img/e8.svg", "q": "La Tetería, Calle San Agustín 9, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e9", "cat": "tapas", "name": "Casa Lola", "addr": "Calle Granada 46, 29015", "text": "A lively, tiled taberna with vermouth on tap and low prices for croquetas, ajoblanco, montaditos and fried aubergine with cane honey. Busy and loud, so go early (13:00 or 20:00) or be ready to wait.", "tip": "Expect a queue", "lat": 36.7214, "lon": -4.4212, "price": 1, "walk": 8, "img": "img/e9.svg", "q": "Casa Lola, Calle Granada 46, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e10", "cat": "tapas", "name": "La Tranca", "addr": "Calle Carretería 92, 29008", "text": "A rowdy, cheerful bar crammed with old record sleeves, with very cheap drinks, house vermouth and simple tapas. The playlist leans to Spanish classics, and the bar staff have been known to sing along. Pure local fun.", "tip": "Standing room only", "lat": 36.7244, "lon": -4.4222, "price": 1, "walk": 8, "img": "img/e10.svg", "q": "La Tranca, Calle Carretería 92, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e11", "cat": "tapas", "name": "Pepa y Pepe", "addr": "Calle Calderería 9, 29008", "text": "A tiny, permanently packed tapas bar with chalkboard raciones, cold beer and boquerones. It feels just like a neighbourhood bar should. Squeeze in at the counter or join the crowd outside.", "tip": "Spills onto the street", "lat": 36.7222, "lon": -4.4205, "price": 1, "walk": 9, "img": "img/e11.svg", "q": "Pepa y Pepe, Calle Calderería 9, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e12", "cat": "tapas", "name": "Mesón Lo Güeno", "addr": "Calle Marín García 9, 29005", "text": "A wood-panelled tapas bar in a little alley off Calle Larios, packed with diners since the 1960s. Good for cured meats, hot montaditos and an enormous choice of tapas, and it's still serving until late.", "tip": "Off Calle Larios · open late", "lat": 36.7194, "lon": -4.4213, "price": 2, "walk": 9, "img": "img/e12.svg", "q": "Mesón Lo Güeno, Calle Marín García 9, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e13", "cat": "tapas", "name": "Casa Lola Uncibay", "addr": "Plaza de Uncibay 8, 29008", "text": "A tapas restaurant on Plaza de Uncibay with tables on the square and a broad menu of tapas and pinchos, including Iberian steak, Caesar salad and vegetarian options. Reviewers single out the pinchos. Service gets mixed reviews, so it's worth going at a quieter time.", "tip": "Terrace on the square · daily 12:30–23:30", "lat": 36.722572, "lon": -4.420155, "price": 2, "walk": 9, "img": "img/e13.svg", "q": "Casa Lola Uncibay, Plaza de Uncibay 8, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e14", "cat": "tapas", "name": "El Pimpi", "addr": "Calle Granada 62, 29015", "text": "A rambling old bodega of patios and barrel rooms, with walls covered in photos of famous visitors and a terrace facing the floodlit Roman Theatre and Alcazaba. Touristy but genuinely atmospheric: have a vermouth, a sweet wine and ensaladilla at dusk. It's one of the places that revived vermouth in the city.", "tip": "Ask for the terrace", "lat": 36.7219, "lon": -4.4177, "price": 2, "walk": 13, "img": "img/e14.svg", "q": "El Pimpi, Calle Granada 62, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e15", "cat": "mid", "name": "La Deriva", "addr": "Alameda de Colón 7, 29001", "text": "A stylish restaurant at the Soho end of the Alameda, serving seasonal Spanish dishes with modern techniques and a long wine list with a strong cheese selection. Good for a relaxed dinner rather than a quick bite.", "tip": "Book ahead · open until midnight", "lat": 36.7181, "lon": -4.4266, "price": 2, "walk": 6, "img": "img/e15.svg", "q": "La Deriva, Alameda de Colón 7, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e16", "cat": "mid", "name": "Alegría Flamenco y Gastronomía", "addr": "Calle Vélez Málaga 6, 29016", "text": "A flamenco tablao with a restaurant, a short walk from the Malagueta beach and Muelle Uno. Shows run every day with a mix of palos, from soleá to bulerías, and you can combine a show with dinner. Book ahead, especially at weekends.", "tip": "Shows about 18:00, 20:00 and 22:30 · 1 hr", "lat": 36.7178, "lon": -4.4112, "price": 2, "walk": 23, "img": "img/e16.svg", "q": "Alegría Flamenco y Gastronomía, Calle Vélez Málaga 6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e17", "cat": "mid", "name": "El Tapeo de Cervantes", "addr": "Calle Cárcer 8, 29012", "text": "A tiny, much-loved tavern doing creative, generous tapas, such as morcilla with quail egg or slow-cooked meats, with a good Málaga wine list. Its sister restaurant El Mesón de Cervantes (Calle Álamos 11) has more room and serves dinner only.", "tip": "Tiny, so book ahead", "lat": 36.7241, "lon": -4.4183, "price": 2, "walk": 13, "img": "img/e17.svg", "q": "El Tapeo de Cervantes, Calle Cárcer 8, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e18", "cat": "mid", "name": "La Cosmo", "addr": "Calle Císter 11, 29015", "text": "Star chef Dani Carnero's informal, Bib Gourmand-rated place behind the cathedral. Sit at the counter and watch an open kitchen send out market fish, his mother's hake salad and seasonal plates. Michelin-standard cooking at bistro prices.", "tip": "Michelin Bib Gourmand", "lat": 36.7206, "lon": -4.4181, "price": 3, "walk": 12, "img": "img/e18.svg", "q": "La Cosmo, Calle Císter 11, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e19", "cat": "mid", "name": "Uvedoble Taberna", "addr": "Calle Císter 15 (corner of Calle Alcazabilla), 29015", "text": "A modern tapas bar loved by locals, with polished takes on classics such as rice dishes, tuna, croquetas and slow-cooked meats. It sits right in the museum quarter, so it's ideal for lunch between the Alcazaba and the Picasso.", "tip": "Book for dinner", "lat": 36.7209, "lon": -4.4172, "price": 2, "walk": 14, "img": "img/e19.svg", "q": "Uvedoble Taberna, Calle Císter 15, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e20", "cat": "mid", "name": "Mesón Mariano", "addr": "Calle Granados 2, 29008", "text": "A family-run favourite since 1988 for seasonal Andalusian cooking. It's famous for artichokes done several ways and for a proper gazpachuelo (Málaga's warm fish and mayonnaise soup). Unflashy, generous and reliably good.", "tip": "Try the artichokes", "lat": 36.7224, "lon": -4.4195, "price": 2, "walk": 10, "img": "img/e20.svg", "q": "Mesón Mariano, Calle Granados 2, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e21", "cat": "mid", "name": "Los Patios de Beatas", "addr": "Calle Beatas 43, 29008", "text": "Two restored 18th-century houses with stained-glass courtyards and more than fifty wines by the glass, including many from Málaga's mountains. Order a few plates to share and let them guide you through the local wines.", "tip": "Wine lovers' choice", "lat": 36.7232, "lon": -4.4197, "price": 2, "walk": 10, "img": "img/e21.svg", "q": "Los Patios de Beatas, Calle Beatas 43, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e22", "cat": "mid", "name": "Beluga", "addr": "Plaza de las Flores 3, 29005", "text": "Chef Diego René cooks seafood from the Alborán Sea with flair, from an à la carte menu or two tasting menus, on one of the old town's prettiest small squares. A step up for a special dinner without the full tasting-menu commitment.", "tip": "Daily lunch & dinner", "lat": 36.7203, "lon": -4.4232, "price": 3, "walk": 5, "img": "img/e22.svg", "q": "Beluga, Plaza de las Flores 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e23", "cat": "splurge", "name": "Kaleja", "addr": "Calle Marquesa de Moya 9, 29015", "text": "Dani Carnero's starred restaurant in the old Jewish quarter. The 'Memoria' tasting menus recreate the Andalusian flavours of his childhood, cooked slowly over embers. Only a handful of tables. Expect roughly €90–120 a head before wine.", "tip": "1 Michelin star · book ~2 weeks ahead", "lat": 36.7212, "lon": -4.4191, "price": 4, "walk": 11, "img": "img/e23.svg", "q": "Kaleja, Calle Marquesa de Moya 9, Málaga", "ta": true, "far": false, "web": "https://restaurantekaleja.com"}, {"id": "e24", "cat": "splurge", "name": "Palodú", "addr": "Calle Sebastián Souvirón 7, 29005", "text": "Málaga's newest star, awarded in the 2026 guide. Chefs Cristina Cánovas and Diego Aguilar cook side by side with no head chef, offering two market-led tasting menus (Alcazul and Palodú), each with an optional wine pairing. The hot ticket in town.", "tip": "Closed Mon, Tue & Sun · New Michelin star 2026", "lat": 36.7191, "lon": -4.4242, "price": 4, "walk": 6, "img": "img/e24.svg", "q": "Palodú, Calle Sebastián Souvirón 7, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e25", "cat": "splurge", "name": "Blossom", "addr": "Museo de Málaga, Palacio de la Aduana (4th floor), Plaza de la Aduana", "text": "Argentine chef Emi Schobert's starred restaurant, rebuilt on the top floor of the Customs House museum after a fire at its old site. Two tasting menus: Esencia (9 courses, about €140) and Confluencia (15 courses, about €220).", "tip": "1 Michelin star", "lat": 36.7204, "lon": -4.416, "price": 4, "walk": 15, "img": "img/e25.svg", "q": "Blossom, Museo de Málaga, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e26", "cat": "splurge", "name": "José Carlos García", "addr": "Café de París site, La Malagueta (confirm the address before visiting)", "text": "Málaga's longest-standing Michelin-starred chef. After 15 years on Muelle Uno he announced a move this autumn back to the refurbished Café de París, where his career began. Confirm the address when you book. Two long tasting menus of modern Andalusian cooking.", "tip": "Confirm the new address", "lat": 36.7199, "lon": -4.4095, "price": 4, "walk": 25, "img": "img/e26.svg", "q": "José Carlos García Restaurante, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e27", "cat": "splurge", "name": "Balausta", "addr": "Palacio Solecio, Calle Granada 57, 29015", "text": "José Carlos García's more relaxed restaurant in a restored 18th-century palace hotel. The courtyard dining room serves his creative Andalusian cooking à la carte, at a fraction of tasting-menu prices.", "tip": "Starred chef, gentler prices", "lat": 36.7221, "lon": -4.4185, "price": 3, "walk": 12, "img": "img/e27.svg", "q": "Balausta, Palacio Solecio, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e28", "cat": "bars", "name": "Ático, AC Hotel Málaga Palacio", "addr": "Calle Cortina del Muelle 1, 29015", "text": "The classic Málaga rooftop: a 15th-floor terrace bar looking straight at the cathedral, the port and the Alcazaba. Cocktails aren't cheap, but the view is the best in town. Open daily from lunchtime until late.", "tip": "Go for sunset", "lat": 36.7185, "lon": -4.4197, "price": 3, "walk": 11, "img": "img/e28.svg", "q": "AC Hotel Málaga Palacio, Calle Cortina del Muelle 1, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e29", "cat": "bars", "name": "Terraza Chinitas", "addr": "Pasaje de Chinitas, 29015", "text": "A two-level rooftop bar tucked into one of the old town's most charming passages, with close-up views of the cathedral towers. More intimate and less formal than the big hotel terraces.", "tip": "Cathedral views", "lat": 36.7202, "lon": -4.4219, "price": 2, "walk": 7, "img": "img/e29.svg", "q": "Terraza Chinitas, Pasaje de Chinitas, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e30", "cat": "bars", "name": "Cobalto 15", "addr": "Muelle Uno, Paseo de la Farola 4, 29016", "text": "One of the city's most inventive cocktail bars, with a menu built around unusual concepts and serious technique. It's on the Muelle Uno waterfront, a longer walk from the hotel.", "tip": "Muelle Uno · check location", "lat": 36.715, "lon": -4.4143, "price": 3, "walk": 21, "img": "img/e30.svg", "q": "Cobalto 15, Muelle Uno, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e31", "cat": "bars", "name": "The Pharmacy", "addr": "Calle García Briz 3, 29005", "text": "A hidden speakeasy dressed as an old apothecary, mixing precise cocktails from vintage-style bottles. Look for the unmarked door. Fun for a nightcap.", "tip": "Unmarked door", "lat": 36.7226, "lon": -4.4222, "price": 3, "walk": 6, "img": "img/e31.svg", "q": "The Pharmacy, Calle García Briz 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e32", "cat": "bars", "name": "La Fábrica de Cruzcampo", "addr": "Calle Trinidad Grund 29, Soho, 29001", "text": "Cruzcampo's craft microbrewery in a big Soho warehouse, brewing its own pale ales and IPAs on site to drink fresh from the tank, with hearty bar food. Relaxed and roomy, with frequent live music.", "tip": "Live music some nights", "lat": 36.7171, "lon": -4.4244, "price": 2, "walk": 9, "img": "img/e32.svg", "q": "La Fábrica de Cruzcampo, Calle Trinidad Grund, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e33", "cat": "gay", "name": "La Calle de Bruselas", "addr": "Plaza de la Merced 16, 29012", "text": "An Art Deco café-bar opened by a Belgian in 1995, now the heart of the plaza's famously open-minded 'acera gay' (gay pavement). Breakfast, tapas, cocktails and people-watching from the always-busy terrace, with the occasional drag performance in the evening.", "tip": "Terrace · all day", "lat": 36.7231, "lon": -4.416, "price": 2, "walk": 15, "img": "img/e33.svg", "q": "La Calle de Bruselas, Plaza de la Merced 16, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e34", "cat": "gay", "name": "Mantón, Bar de Copas", "addr": "Calle San Juan de Letrán 6, 29012", "text": "A small, stylish bar de copas for conversation rather than dancing, with good cocktails and warm, attentive hosts. It's the ideal first drink of the night, just off Plaza de la Merced.", "tip": "Early-evening drinks", "lat": 36.7244, "lon": -4.4165, "price": 2, "walk": 15, "img": "img/e34.svg", "q": "Mantón, Bar de Copas, Calle San Juan de Letrán 6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e35", "cat": "gay", "name": "Kipfer & Lover", "addr": "Calle San Juan de Letrán 21, 29012", "text": "A lively, friendly bar on the same street, drawing a younger, international crowd (though everyone's welcome). Modern décor, comfortable seats and a good place to meet people.", "tip": "Livelier later", "lat": 36.7252, "lon": -4.4172, "price": 2, "walk": 15, "img": "img/e35.svg", "q": "Kipfer & Lover, Calle San Juan de Letrán 21, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e36", "cat": "gay", "name": "Lolita's", "addr": "Plaza de San Francisco 2, 29008", "text": "A classic, unpretentious gay bar from the team behind Lola's Copas, with pop anthems and dance hits and a mixed crowd of regulars and visitors. Handily it's the closest to your hotel, just over the Santo Domingo bridge.", "tip": "Busy at weekends", "lat": 36.7232, "lon": -4.42, "price": 2, "walk": 10, "img": "img/e36.svg", "q": "Lolita's, Plaza de San Francisco 2, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e37", "cat": "gay", "name": "La Comedia", "addr": "Calle Comedias 15, 29008", "text": "A cheerful bar known for its nightly drag shows, which are played for big laughs. You'll still have fun with limited Spanish. Get there in good time for a seat when the show starts.", "tip": "Drag shows · closed Mon & Tue", "lat": 36.7224, "lon": -4.4216, "price": 2, "walk": 7, "img": "img/e37.svg", "q": "La Comedia, Calle Comedias 15, Málaga", "ta": true, "far": false, "web": ""}, {"id": "e38", "cat": "gay", "name": "Theatro Club", "addr": "Calle Lazcano 5, 29008", "text": "Not exclusively gay but very LGBTQ+-popular: a late-night club mixing concerts, comedy and live jazz with disco until dawn. It's the place to end the night, and won't get going until well after midnight.", "tip": "Late · mixed crowd", "lat": 36.7234, "lon": -4.4232, "price": 2, "walk": 6, "img": "img/e38.svg", "q": "Theatro Club, Calle Lazcano 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x1", "cat": "bars", "name": "Renard Cocktail Club", "addr": "Calle Duque de la Victoria 7, 29015", "text": "An intimate, low-lit cocktail bar off Calle Larios, with a short menu of classic and signature drinks made with real care. Among the best-rated cocktail bars in the city. Open Tuesday to Saturday from 19:00 (closed Sunday and Monday).", "tip": "Book a table at weekends", "lat": 36.7209, "lon": -4.4183, "price": 2, "walk": 12, "img": "img/x1.svg", "q": "Renard Cocktail Club, Calle Duque de la Victoria 7, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x2", "cat": "bars", "name": "Chester & Punk", "addr": "Calle Méndez Núñez 4, 29008", "text": "A playful, neon-and-graffiti room that pours inventive, competition-grade cocktails. Favourites from the 'Chester' classics to the wilder 'Punk' collection. Open late, until 03:00 at weekends, with regular live music.", "tip": "Open until 03:00 at weekends", "lat": 36.7202, "lon": -4.4198, "price": 2, "walk": 10, "img": "img/x2.svg", "q": "Chester & Punk, Calle Méndez Núñez 4, Málaga", "ta": true, "far": false, "web": "https://www.chesterandpunk.com"}, {"id": "x3", "cat": "bars", "name": "Mañana Cocktail Bar", "addr": "Calle San Juan de Letrán 7, 29012", "text": "A lively cocktail bar near Plaza de la Merced with creative drinks and a relaxed buzz. One of the better-reviewed spots on the San Juan de Letrán strip, so it pairs well with the gay bars nearby.", "tip": "Good for a first drink", "lat": 36.7248, "lon": -4.417, "price": 2, "walk": 15, "img": "img/x3.svg", "q": "Mañana Cocktail Bar, Calle San Juan de Letrán 7, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x4", "cat": "bars", "name": "La Destilería", "addr": "Calle Beatas 1, 29008", "text": "A cocktail bar making its own distillates, with live music and drinks that run late into the early hours. The bar is set in a restored old-town house, which gives it a warm, slightly bohemian feel.", "tip": "Live music some nights", "lat": 36.7226, "lon": -4.4188, "price": 2, "walk": 11, "img": "img/x4.svg", "q": "La Destilería, Calle Beatas 1, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x5", "cat": "bars", "name": "Puerta Oscura", "addr": "Calle Molina Lario 5, 29015", "text": "A hushed, old-fashioned cocktail bar near the cathedral, with 19th-century velvet, classical music and slow, carefully made drinks. The place for a quiet, grown-up drink rather than a loud night out.", "tip": "Quiet, classical music", "lat": 36.7196, "lon": -4.419, "price": 2, "walk": 11, "img": "img/x5.svg", "q": "Puerta Oscura, Calle Molina Lario 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x6", "cat": "bars", "name": "La Terraza de la Alcazaba", "addr": "Calle Alcazabilla 12, 29015 (rooftop of Hostel Alcazaba Premium)", "text": "A rooftop cocktail bar on the fifth floor of a hotel, with floodlit views of the Alcazaba and Gibralfaro. Good value for a view like this. Open Monday to Thursday from 15:00 and Friday to Sunday from 13:00.", "tip": "Floodlit castle views", "lat": 36.7209, "lon": -4.4163, "price": 3, "walk": 15, "img": "img/x6.svg", "q": "La Terraza de la Alcazaba, Calle Alcazabilla 12, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x7", "cat": "bars", "name": "La Terraza Molina Lario", "addr": "Calle Molina Lario 20, 29015 (8th floor)", "text": "An eighth-floor rooftop bar with a pool deck and front-row views of the cathedral and the port. Cocktails are pricier than in the old town, but the setting is hard to beat at sunset.", "tip": "Pool deck and cathedral views", "lat": 36.7195, "lon": -4.4186, "price": 3, "walk": 12, "img": "img/x7.svg", "q": "La Terraza Molina Lario, Calle Molina Lario 20, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x8", "cat": "bars", "name": "ZZ Pub", "addr": "Calle Tejón y Rodríguez 6, 29008", "text": "A lively, budget-friendly bar and concert venue known for blues and jazz nights. Good for an unpretentious evening with local music, away from the tourist circuit.", "tip": "Blues & jazz nights", "lat": 36.7239, "lon": -4.4215, "price": 1, "walk": 8, "img": "img/x8.svg", "q": "ZZ Pub, Calle Tejón y Rodríguez 6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x9", "cat": "galleries", "name": "Benedito Art Gallery", "addr": "Calle Niño de Guevara, local 2, 29008", "text": "A small, free-entry exhibition space in the old town showing contemporary painting and prints by Málaga and Spanish artists. Quiet and easy to combine with a stroll around the Plaza de la Merced.", "tip": "Free entry · Tue–Thu 11:00–13:30 & 17:30–20:00, Fri 17:30–20:00", "lat": 36.7243, "lon": -4.4197, "price": 0, "walk": 11, "img": "img/x9.svg", "q": "Benedito Art Gallery, Calle Niño de Guevara, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x10", "cat": "galleries", "name": "Galería Taller Gravura", "addr": "Calle Coronel 3, 1º, 29005", "text": "A printmaking workshop and gallery with one of the most significant lithographic workshops in Spain. You can see prints being made, and buy original editions. Open weekdays, usually around 11:00–13:00 and 18:00–21:00.", "tip": "Original prints for sale", "lat": 36.7213, "lon": -4.4229, "price": 0, "walk": 5, "img": "img/x10.svg", "q": "Galería Taller Gravura, Calle Coronel 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x11", "cat": "galleries", "name": "Espacio Tres", "addr": "Calle Moscatel, 29008 (by appointment)", "text": "A gallery, cultural centre and artists' association since 1995, promoting artists from Málaga and exchanging shows with galleries in Yorkshire, Barcelona, Sintra and Lisbon. Visits are by appointment, so ring ahead.", "tip": "Not confirmed on Google · check before visiting", "lat": 36.7226, "lon": -4.4218, "price": 0, "walk": 7, "img": "img/x11.svg", "q": "Espacio Tres, Calle Moscatel, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x12", "cat": "galleries", "name": "Porticus Gallery", "addr": "Calle Compañía 3, 29008", "text": "A small gallery a few steps from the Carmen Thyssen, showing contemporary Spanish art in a compact space. Open mornings and early evenings on weekdays, so check before you go.", "tip": "Not confirmed on Google · check before visiting", "lat": 36.7213, "lon": -4.424, "price": 0, "walk": 4, "img": "img/x12.svg", "q": "Porticus Gallery, Calle Compañía 3, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x13", "cat": "shops", "name": "Mercado de Salamanca", "addr": "Calle San Bartolomé 1, 29013 (El Molinillo)", "text": "A 1920s Neo-Mudéjar market in El Molinillo, with tiled arches over stalls of fish, meat, fruit and vegetables. It's off the tourist trail and very local. Go in the morning, when the fish is freshest, and try a bar stool for a coffee.", "tip": "Neo-Mudéjar tilework · Mon–Sat mornings", "lat": 36.7225, "lon": -4.4152, "price": 1, "walk": 16, "img": "img/x13.svg", "q": "Mercado de Salamanca, Calle San Bartolomé 1, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x14", "cat": "shops", "name": "Mercado de Huelin", "addr": "Calle la Hoz 37, 29002", "text": "Málaga's second-largest market, with around 160 stalls of fresh fish, meat and produce in the Huelin fishing district. Best for seafood, and for a glimpse of everyday life. About a 30-minute walk or a short bus ride west of the centre.", "tip": "Best for fresh fish · Mon–Sat mornings", "lat": 36.7026, "lon": -4.4382, "price": 1, "walk": 38, "img": "img/x14.svg", "q": "Mercado de Huelin, Calle la Hoz 37, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x15", "cat": "outdoor", "name": "Playa de La Malagueta", "addr": "Paseo Marítimo, La Malagueta, 29016", "text": "The city-centre beach, a 10-minute walk from the old town along the seafront. Sand, a seafront promenade for walking or cycling, and beach bars for lunch. Shady in the afternoons, and perfect in autumn sunshine.", "tip": "Walk from the old town", "lat": 36.7187, "lon": -4.4096, "price": 0, "walk": 25, "img": "img/x15.svg", "q": "Playa de La Malagueta, Paseo Marítimo, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x16", "cat": "outdoor", "name": "Caminito del Rey", "addr": "North entrance (start), Desfiladero de los Gaitanes, El Chorro (about 1 hr by car; organised transfers from Málaga)", "text": "A famous walk along a cliff-hugging boardwalk above the Gaitanes gorge, about 1 hour north of Málaga. The official site sells general admission for €10, or guided tours for €18. Book ahead, as tickets sell out, and wear sturdy shoes. Drive, or book a guided transfer from Málaga.", "tip": "Official tickets: caminitodelrey.info · €10", "lat": 36.9288, "lon": -4.8015, "price": 0, "walk": 660, "img": "img/x16.svg", "q": "Caminito del Rey, North entrance, Málaga", "ta": true, "far": true, "web": "https://www.caminitodelrey.info"}, {"id": "x17", "cat": "outdoor", "name": "Pedregalejo beach & chiringuitos", "addr": "Paseo Marítimo de Pedregalejo, 29017", "text": "A fishing village beach east of the centre, with a row of beach bars (chiringuitos) serving espetos, sardines grilled on canes over embers. The beach promenade is a lovely late-afternoon walk. Take a bus or taxi, about 15 minutes out.", "tip": "Espetos de sardinas", "lat": 36.7223, "lon": -4.3712, "price": 2, "walk": 80, "img": "img/x17.svg", "q": "Pedregalejo beach & chiringuitos, Paseo Marítimo de Pedregalejo, Málaga", "ta": true, "far": true, "web": ""}, {"id": "x18", "cat": "world", "name": "Al Yamal", "addr": "Calle Blasco de Garay 7, 29001 (Soho)", "text": "Family-run for four decades, serving Moroccan food with real authenticity: tagines, couscous and kefta (spiced meatballs). The Moroccan option in the city centre, and a relaxed, unfussy place for a sharing dinner.", "tip": "Closed Sun & Mon · Tagines & couscous · family-run", "lat": 36.7159, "lon": -4.4224, "price": 2, "walk": 12, "img": "img/x18.svg", "q": "Al Yamal, Calle Blasco de Garay 7, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x19", "cat": "world", "name": "La Caravana (Cocina Viajera)", "addr": "Calle José Denis Belgrano 25, 29008", "text": "A creative, globe-trotting restaurant near the Soho end of the old town, mixing Latin American, African and other flavours in a menu built around fresh ingredients and homemade sauces. Strong vegetarian, vegan and gluten-free choices, and a quieter spot away from the main tourist routes.", "tip": "Creative world menu · vegetarian options", "lat": 36.722556, "lon": -4.419458, "price": 2, "walk": 10, "img": "img/x19.svg", "q": "La Caravana (Cocina Viajera), Calle José Denis Belgrano 25, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x20", "cat": "world", "name": "Kosei Ramen", "addr": "Calle Carretería 56, 29008", "text": "A small, cosy, authentic Japanese ramen bar with tonkotsu and vegan ramen, gyoza and donburi. Around €20 a head, and a casual, friendly stop after the Carretería bars.", "tip": "Tonkotsu ramen · about €20 a head", "lat": 36.7234, "lon": -4.4221, "price": 2, "walk": 7, "img": "img/x20.svg", "q": "Kosei Ramen, Calle Carretería 56, Málaga", "ta": true, "far": false, "web": "https://koseiramen.com"}, {"id": "x21", "cat": "world", "name": "Ta-Kumi", "addr": "Calle Mundo Nuevo 4, 29012", "text": "A long-running Japanese restaurant in the centre, with a sushi and robata counter that draws on the day's catch from the Atarazanas market. A Michelin Guide listing, and a step up from the everyday ramen bars.", "tip": "Sushi & robata counter · Michelin listed", "lat": 36.7224, "lon": -4.419, "price": 3, "walk": 11, "img": "img/x21.svg", "q": "Ta-Kumi, Calle Mundo Nuevo 4, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x22", "cat": "world", "name": "Terra Mía", "addr": "Calle Granada 26, 29015", "text": "An authentic Neapolitan pizzeria with a working wood oven at the heart of the room. Light dough and fresh ingredients, plus home-style Calabrian dishes. Reliably popular with locals and visitors alike.", "tip": "Neapolitan wood-fired pizza", "lat": 36.7218, "lon": -4.4184, "price": 2, "walk": 12, "img": "img/x22.svg", "q": "Terra Mía, Calle Granada 26, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x23", "cat": "world", "name": "Niña Bonita Cantina", "addr": "Calle Martínez Campos 6, 29001 (Soho)", "text": "Traditional Mexican cooking by a Panamanian-born chef, in a lively cantina in Soho. Slow-cooked dishes, a good tequila and mezcal selection, and a buzzy atmosphere. Expect it to be busy in the evenings.", "tip": "Slow-cooked Mexican · lively", "lat": 36.717, "lon": -4.425, "price": 2, "walk": 9, "img": "img/x23.svg", "q": "Niña Bonita Cantina, Calle Martínez Campos 6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x24", "cat": "world", "name": "Cantina Canalla Soho", "addr": "Calle Trinidad Grund 28, 29001 (Soho)", "text": "A Mexican and Latin cantina with a strong cocktail menu and a rowdy, fun atmosphere. Its Google rating is high because the margaritas and the energy are both very good. A natural stop before the Soho craft brewery.", "tip": "Possibly renamed Despecha Taberna · check before visiting", "lat": 36.7168, "lon": -4.4241, "price": 2, "walk": 9, "img": "img/x24.svg", "q": "Cantina Canalla Soho, Calle Trinidad Grund 28, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x25", "cat": "world", "name": "Mamuchis Cocina del Mundo", "addr": "Calle Casas de Campos 27, 29001 (Soho)", "text": "A 'world kitchen' in Soho with Mexican, Asian and Greek dishes on one menu, so each person can order something different. Popular with groups, with a good value set of plates to share.", "tip": "Mexican, Asian & Greek on one menu", "lat": 36.7165, "lon": -4.4265, "price": 2, "walk": 9, "img": "img/x25.svg", "q": "Mamuchis Cocina del Mundo, Calle Casas de Campos 27, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x26", "cat": "world", "name": "Pitaya Sabores Thai", "addr": "Calle Compañía, 29008", "text": "A Thai street-food style restaurant on Calle Compañía near the centre, with quick service and generous portions. Pad thai, red curry and other classics are popular, and there's a lunch combo menu.", "tip": "Open daily from 12:00 · lunch combo", "lat": 36.721419, "lon": -4.423955, "price": 2, "walk": 4, "img": "img/x26.svg", "q": "Pitaya Sabores Thai, Calle Compañía, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x27", "cat": "world", "name": "Amigos Grill Muelle Uno", "addr": "Muelle Uno, Puerto de Málaga, 29016", "text": "Mexican, Greek and Indian food on the waterfront at Muelle Uno, open from midday until midnight every day. A good all-round choice when you want something different from tapas, with views of the harbour.", "tip": "Open daily 12:00–00:00", "lat": 36.7163, "lon": -4.4165, "price": 2, "walk": 17, "img": "img/x27.svg", "q": "Amigos Grill Muelle Uno, Muelle Uno, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x28", "cat": "sights", "name": "Hammam Al Ándalus", "addr": "Plaza de los Mártires 5, 29008", "text": "A restored Nasrid-style Arab bath in the old town, with hot, warm and cold pools, steam rooms and mint tea. Add a massage or a kessa scrub for a longer session. Bathing is mixed, apart from the changing rooms, so check the booking options before you go.", "tip": "Book ahead · sessions every two hours", "lat": 36.7219, "lon": -4.4232, "price": 3, "walk": 5, "img": "img/x28.svg", "q": "Hammam Al Ándalus, Plaza de los Mártires 5, Málaga", "ta": true, "far": false, "web": "https://malaga.hammamalandalus.com"}, {"id": "x29", "cat": "bars", "name": "Sherlock Holmes Pub", "addr": "Calle Molina Lario 4, 29015", "text": "A British-style pub in the old town, with classic pub food, draught beers and a slice of home for expats and visitors who miss a proper pint. Good for a football match or a relaxed late afternoon.", "tip": "A proper British pub", "lat": 36.7199, "lon": -4.4188, "price": 2, "walk": 12, "img": "img/x29.svg", "q": "Sherlock Holmes Pub, Calle Molina Lario 4, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x30", "cat": "sights", "name": "Tourist office (Junta de Andalucía)", "addr": "Calle Compañía 40, 29008 (Junta de Andalucía office)", "text": "The regional tourist office, in a historic building on Calle Compañía. Maps, guides and advice for the city and the province. Tel. +34 951 308 911. Check the current hours before you go, as sources differ, and the municipal office on Plaza de la Marina was closed for works from April 2026. Ben Gabirol reception in Plaza de la Judería is open daily from 09:00 to 19:00.", "tip": "Tel. +34 951 308 911 · check hours", "lat": 36.7218, "lon": -4.4243, "price": 0, "walk": 3, "img": "img/x30.svg", "q": "Tourist office (Junta de Andalucía), Calle Compañía 40, Málaga", "ta": false, "far": false, "web": ""}, {"id": "x31", "cat": "bars", "name": "Central Beers", "addr": "Calle Cárcer 6, 29008", "text": "A craft beer bar on the semi-pedestrian Calle Cárcer, with a rotating tap list of Spanish and international brews and a relaxed, retro-styled room. The food is simple, so come for the beer.", "tip": "Opens 18:00 on weekdays", "lat": 36.723629, "lon": -4.419702, "price": 2, "walk": 10, "img": "img/x31.svg", "q": "Central Beers, Calle Cárcer 6, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x32", "cat": "bars", "name": "Birra Deluxe", "addr": "Plaza de la Merced 5, 29012", "text": "A craft beer bar and bottle shop on Plaza de la Merced, with a long tap list and fridges stocked with cans from around the world. Staff are known for guiding you to a beer that suits your taste.", "tip": "Bottle shop too · opens 17:00", "lat": 36.723037, "lon": -4.418271, "price": 2, "walk": 12, "img": "img/x32.svg", "q": "Birra Deluxe, Plaza de la Merced 5, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x33", "cat": "bars", "name": "La Madriguera", "addr": "Calle Carretería 73, 29008", "text": "A snug craft beer bar on Calle Carretería, with a rotating selection on tap, a bigger choice in cans, and small plates such as mini burgers. Regulars praise the staff's recommendations.", "tip": "Small room · go early", "lat": 36.723849, "lon": -4.422578, "price": 2, "walk": 7, "img": "img/x33.svg", "q": "La Madriguera, Calle Carretería 73, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x34", "cat": "bars", "name": "La Botica de la Cerveza", "addr": "Calle Victoria 13, 29012", "text": "A relaxed beer bar on Calle Victoria, away from the main tourist crowds, with a large range of bottles and cans and a few taps. Ask the bartender for suggestions by style.", "tip": "Hidden gem · bottle selection", "lat": 36.724018, "lon": -4.416208, "price": 1, "walk": 15, "img": "img/x34.svg", "q": "La Botica de la Cerveza, Calle Victoria 13, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x35", "cat": "bars", "name": "3 Monos Craft Beer", "addr": "Calle Lisboa 30, 29006", "text": "The brewery and taproom of 3 Monos, on the western side of the city, where you can see the fermenters and try the beers on site. It opens on limited days, and visits can also be arranged in advance.", "tip": "Open Fridays 18:00–23:00 only · check before you go", "lat": 36.702194, "lon": -4.47382, "price": 2, "walk": 77, "img": "img/x35.svg", "q": "3 Monos Craft Beer, Calle Lisboa 30, Málaga", "ta": true, "far": true, "web": ""}, {"id": "x36", "cat": "bars", "name": "Diez Cabezas Brewing", "addr": "Calle Sigfrido 31, 29006", "text": "A small brewery taproom where you can drink freshly brewed beer from the tap or take bottles away. The beers change regularly, and the team will advise what to try. Soft drinks and snack platters are available.", "tip": "Brewery taproom · check hours", "lat": 36.71003, "lon": -4.469117, "price": 2, "walk": 65, "img": "img/x36.svg", "q": "Diez Cabezas Brewing, Calle Sigfrido 31, Málaga", "ta": true, "far": true, "web": ""}, {"id": "x37", "cat": "bars", "name": "Hop Scotch Craft Beer & Whisky", "addr": "Calle Correo de Andalucía 6, 29004", "text": "A neighbourhood craft beer and whisky bar on the Cádiz road, with a wide tap and can list, local brews from Málaga and Algeciras, and lambics. It's a longer trip from the centre, but a good local stop.", "tip": "Closed Mon & Tue · outside centre", "lat": 36.689582, "lon": -4.447945, "price": 2, "walk": 66, "img": "img/x37.svg", "q": "Hop Scotch Craft Beer & Whisky, Calle Correo de Andalucía 6, Málaga", "ta": true, "far": true, "web": ""}, {"id": "x38", "cat": "bars", "name": "Bodegas Quitapenas", "addr": "Calle Marín García 4, 29005", "text": "A century-old bodega in the old town, pouring Málaga wines and house vermouth beside classic bodega plates such as boquerones and fried fish. It's a good place for a late-morning or early-evening glass. Google lists it under its restaurant name, Taberna Quitapenas Marín.", "tip": "Open 11:00–16:00 and 20:00–23:00", "lat": 36.719261, "lon": -4.422696, "price": 2, "walk": 7, "img": "img/x38.svg", "q": "Bodegas Quitapenas, Calle Marín García 4, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x39", "cat": "bars", "name": "Casa de Vinos La Odisea", "addr": "Subida a la Coracha 2, 29016", "text": "A small wine house in La Coracha, near the bullring and the castle, with barrels holding only wines from the Málaga province. It's served beside plates of fried fish and cold dishes, and the room is cosy and family-run.", "tip": "Province wines only · open from noon", "lat": 36.721227, "lon": -4.412674, "price": 2, "walk": 20, "img": "img/x39.svg", "q": "Casa de Vinos La Odisea, Subida a la Coracha 2, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x40", "cat": "bars", "name": "Anyway Wine Bar", "addr": "Paseo de la Farola 8, 29016", "text": "A natural and low-intervention wine bar on the Paseo de la Farola in La Malagueta. Staff will let you taste before you choose a bottle, and there are boards of cheese, Iberian ham and some of the best croquettes in the city. Many of the wines are from local producers.", "tip": "Opens 19:00 weekdays · 14:00 weekends", "lat": 36.71737, "lon": -4.412301, "price": 3, "walk": 22, "img": "img/x40.svg", "q": "Anyway Wine Bar, Paseo de la Farola 8, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x41", "cat": "bars", "name": "El Gallo Ronco", "addr": "Plaza de las Flores 1, 29005", "text": "A family-run tapas bar on Plaza de las Flores, known for dishes such as thin pork loin with pepper and lemon, eaten wrapped in picos camperos. Flamenco shows are staged in an intimate room next door, so it's a good choice for an evening out.", "tip": "Flamenco next door · check the schedule", "lat": 36.720617, "lon": -4.42212, "price": 2, "walk": 7, "img": "img/x41.svg", "q": "El Gallo Ronco, Plaza de las Flores 1, Málaga", "ta": true, "far": false, "web": ""}, {"id": "x42", "cat": "cash", "name": "Unicaja head office (cash machine: check on arrival)", "addr": "Avenida de Andalucía 10–12, 29007 (Unicaja head office)", "text": "Unicaja's head office, confirmed on the bank's own documents. Unicaja is reported to charge little or nothing for withdrawals, but I could not confirm that a cash machine is at this address, or what it charges a foreign card. Use Unicaja's own ATM locator to find the nearest machine, and check the fee for your card before you withdraw.", "tip": "Confirm the ATM and fee before you rely on it", "lat": 36.7185, "lon": -4.4325, "price": 0, "walk": 10, "img": "img/x42.svg", "q": "Unicaja head office (cash machine: check on arrival), Avenida de Andalucía 10–12, Málaga", "ta": false, "far": false, "web": "https://www.unicajabanco.es"}, {"id": "x43", "cat": "cash", "name": "Unicaja cash machine, Plaza del Siglo", "addr": "Plaza del Siglo 1, 29015", "text": "A Unicaja cash machine on Plaza del Siglo, open 24 hours. Visitors have reported no fee on withdrawals with some UK and online bank cards, but that varies by card, so check your bank's rules before you withdraw.", "tip": "Open 24 hours · reported fee-free for some cards", "lat": 36.721632, "lon": -4.420013, "price": 0, "walk": 9, "img": "img/x43.svg", "q": "Unicaja cash machine, Plaza del Siglo, Plaza del Siglo 1, Málaga", "ta": false, "far": false, "web": "https://www.unicajabanco.es"}], "hotel": {"name": "Sallés Hotel Málaga Centro", "addr": "Calle Mármoles 6, 29007 Málaga", "tel": "+34 952 07 02 16", "web": "hotelmalagacentro.com", "lat": 36.72165, "lon": -4.42647}};